{
  "contract": "Ring",
  "closure": {
    "site_function": "addLiquidity",
    "site_call": ".call",
    "functions": [
      "burn",
      "transfer",
      "transferFrom",
      "addLiquidity"
    ],
    "justification": "These functions interact with the exposed storage variables _balances, _inTaxSwap, _isLP, and _primaryLP."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "burn",
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "addLiquidity": 1
    }
  },
  "phases": {
    "function": "addLiquidity",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "The amount of tokens in flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances + _swapLimit == _totalSupply + inFlight",
    "stable_formula": "_sum__balances + _swapLimit == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances + _swapLimit == _totalSupply",
    "rule": "The exposure invariant ensures that the sum of balances and swap limit equals the total supply, accounting for in-flight tokens during reentrancy."
  }
}
